 *   hardware has been given one.  The wait, and everything that publishes
 *   the result, belongs to vepu_job_work(), which is queued here as work and
 *   runs when the interrupt has been taken.  The reason for the split is the
 *   caller: this runs inside the queue operation the application is waiting
 *   on, and the ~24 ms the encoder takes for a picture is exactly the time
 *   that application needed for everything else it is doing.
 *
 *   Called with priv->lock held -- see vepu_service().
 *
 ****************************************************************************/

static int vepu_service_locked(FAR struct rk3576_vepu_codec_priv_s *priv)
{
  FAR struct v4l2_buffer *obuf;
  FAR struct v4l2_buffer *cbuf;
