/* Flag a capture buffer as the end of the stream, and say so as an event.
 *
 * A flush is a protocol marker and not a picture, so a buffer that carries
 * nothing but the marker has to say it carries nothing: its length is
 * cleared, because leaving the field alone would leave whatever the
 * container's last use wrote there, and the application would take it for a
 * frame of that length.  A buffer that also holds the last frame keeps its
 * length and is marked on top of the frame's own flag.
 *
 * The event is what tells a waiter that is not counting buffers that the
 * stream is over; the flag is what tells one that is.
 */

static void vepu_flag_eos(FAR struct rk3576_vepu_codec_priv_s *priv,
                          FAR struct v4l2_buffer *cbuf, bool encoded)
{
  struct v4l2_event evt;

  if (encoded)
    {
      cbuf->flags |= V4L2_BUF_FLAG_LAST;
    }
  else
    {
      cbuf->bytesused = 0;
      cbuf->flags = V4L2_BUF_FLAG_LAST;
    }

  priv->eos_pending = false;

  memset(&evt, 0, sizeof(evt));
  evt.type = V4L2_EVENT_EOS;
  codec_queue_event(priv->cookie, &evt);
}
