/****************************************************************************
 * Name: vepu_job_work
 *
 * Description:
 *   The completion of a job, on the work queue: wait for the interrupt the
 *   start half left running, then publish or discard what it produced.
 *
 *   It cannot be done in the interrupt handler.  The wait itself has to be
 *   somewhere that is allowed to sleep, and the tail does cache maintenance
 *   over the destination and touches the framework's buffer lists, neither of
 *   which an interrupt handler may do.
 *
 *   HPWORK rather than LPWORK, and deliberately.  The completion holds
 *   g_vepu_lock until it has run -- that is the whole of what makes the
 *   hardware "one job at a time" -- so the next frame cannot be started
 *   until this has finished, and queueing behind the camera's demosaic job,
 *   which is the LPWORK queue's other resident and costs about 15 ms, would
 *   add that to every frame period.  What runs here is one cache
 *   invalidation, one copy of the bitstream and a handful of list
 *   operations, all bounded and all short, so the high-priority queue is
 *   where it belongs: nothing else is delayed for long, and the encoder
 *   never waits behind something that has no interest in it.
 *
 ****************************************************************************/

static void vepu_job_work(FAR void *arg)
{
  FAR struct rk3576_vepu_codec_priv_s *priv = arg;
  int ret;

  ret = rk3576_vepu_finish(&priv->job_frm, &priv->job_slice, &priv->job_result);

  nxmutex_lock(&priv->lock);
  vepu_job_complete(priv, ret);
  priv->job_running = false;
  nxmutex_unlock(&priv->lock);

  /* The hardware is free again, and the completion may have been what a
   * waiting frame was waiting for.  Nothing else is going to look at the
   * queues after this, so the next job is started from here.
   */

  ret = vepu_service(priv);
  if (ret < 0)
    {
      _err("ERROR: VEPU0 codec could not start the next frame: %d\n", ret);
    }
}
```

