/****************************************************************************
 * Name: vepu_service
 *
 * Description:
 *   Start the next frame, if the encoder is free for one.
 *
 *   The lock is taken here because the two callers are different threads:
 *   the queue operations that run in the application's context, and the
 *   completion that runs in the work queue's.  Both look at the pending
 *   counters and take containers from the framework's queues, so they have
 *   to be one at a time.
 *
 ****************************************************************************/

static int vepu_service(FAR struct rk3576_vepu_codec_priv_s *priv)
{
