/****************************************************************************
 * Name: vepu_job_settle
 *
 * Description:
 *   Wait for the job in flight, if there is one, and drop what it produced.
 *
 *   Called where the device is being wound down -- a stream stop, or the
 *   last open being closed -- and the two containers the job holds are about
 *   to stop being meaningful: the framework frees them on the final close,
 *   and an application that stopped the stream is entitled to ask for its
 *   buffers back or to free the buffer pool before the completion would have
 *   reached it.  The completion is therefore taken off the queue, or waited
 *   for if it is already running, and whatever is still with the hardware is
 *   waited for here; the frame it produces is not published, because the
 *   stream it would belong to is over.
 *
 *   A job cannot be stopped once started -- the encoder has no abort that
 *   leaves it usable -- so the wait is the job's own, a few tens of
 *   milliseconds at worst.
 *
 ****************************************************************************/

static void vepu_job_settle(FAR struct rk3576_vepu_codec_priv_s *priv)
{
  /* -ENOENT is the ordinary case of no completion queued, and is not a
   * failure.  The loop inside work_cancel_sync() is what covers a
   * completion that started the next job before it noticed the queue's
   * state -- that job is then still running and is waited for below.
   */

  work_cancel_sync(HPWORK, &priv->work);

  nxmutex_lock(&priv->lock);
  if (priv->job_running)
    {
      rk3576_vepu_finish(&priv->job_frm, &priv->job_slice, &priv->job_result);
      priv->job_running = false;
    }

  nxmutex_unlock(&priv->lock);
}
