```c
/* Wait for the next thing to do, and do the part of it the server owns.
 *
 * This is the only place the loop sleeps, and it sleeps on everything that
 * can wake it at once: whatever the frame in progress is waiting for, and
 * every socket the server has.  What the frame is waiting for depends on
 * where it is -- with no frame in flight it is the camera's next frame, and
 * with one it is the encoder, which is where the job that was started when
 * the frame was queued reports back.  The camera is deliberately not in the
 * second set: the next frame cannot be taken until this one is out of the
 * way, and in the modes that encode in place the buffer the camera would
 * hand over is the one the encoder is reading.
 *
 * Returns true when the camera has a frame waiting to be taken, which is only
 * ever true in the first of the two states.  A source that is not the camera
 * has its own pacing and is never waited for; for those, and for a frame in
 * flight, this only serves the sockets and returns false, which the paths
 * that do not need a camera frame ignore.
 */

static bool camenc_wait(int camfd, int encfd, bool inflight)
{
  struct pollfd fds[CAMENC_WAIT_FDS];
  int nwait = 0;
  int n;
  uint64_t mark;

  if (inflight)
    {
      fds[0].fd = encfd;
      fds[0].events = POLLIN | POLLOUT;
      fds[0].revents = 0;
      nwait = 1;
    }
  else if (camfd >= 0)
    {
      fds[0].fd = camfd;
      fds[0].events = POLLIN;
      fds[0].revents = 0;
      nwait = 1;
    }

  n = nwait + camenc_ws_fds(&g_ws, &fds[nwait], CAMENC_WAIT_FDS - nwait);

  mark = camenc_now_us();

  if (poll(fds, (nfds_t)n, nwait != 0 ? CAMENC_WAIT_MS : 0) < 0 &&
      errno != EINTR)
    {
      /* Nothing to say and nothing to do about it: the loop has no frame
       * either way, and the next round asks again.
       */

      return false;
    }

  /* The wait is accounted as the camera stage, which is what that stage has
   * always measured -- the time the loop spends with nothing to do.  It now
   * covers the encode as well, because that is a wait the loop makes here
   * rather than inside the queue operation; the dequeue that follows no
   * longer waits, so the figure stays comparable with runs that measured a
   * blocking one.
   */

  camenc_stage_account(CAMENC_STAGE_CAMERA, mark);

  mark = camenc_now_us();

  camenc_ws_ready(&g_ws, &fds[nwait], n - nwait);

  camenc_stage_account(CAMENC_STAGE_SERVE, mark);

  return !inflight && nwait != 0 && (fds[0].revents & POLLIN) != 0;
}
```

